import math

def odleglosc(x, y, cel):
    return math.hypot(x - cel[0], y - cel[1])

probe = [odleglosc(7, 7, (7, 7)), odleglosc(8, 7, (7, 7)), odleglosc(10, 11, (7, 7))]
odleglosc_gotowa = all(math.isclose(a, b) for a, b in zip(probe, [0, 1, 5]))
print('✓ Obliczanie odległości działa!' if odleglosc_gotowa else f'Sprawdź funkcję: otrzymano {probe}, oczekiwano [0, 1, 5].')

